      const draw=()=>{set(`<div class="xp-shell xp-mines">${header('CAREFUL NOW', 'Sweep the garden', `${total-flags.size} hazards remain · right-click or flag mode to mark`)}<div class="xp-mine-tools"><button class="xp-flag-mode" id="xp-flag-mode">🚩 Flag mode: ${flagMode?'on':'off'}</button><button class="xp-flag-mode" id="xp-new-board">New board</button></div><div class="xp-mine-board" style="--xp-size:${size}">${Array.from({length:size*size},(_,i)=>`<button class="xp-mine-cell ${opened.has(i)?'open':''} ${mines.has(i)&&lost?'mine':''} ${flags.has(i)?'flag':''}" data-mine="${i}" ${opened.has(i)||lost?'disabled':''}>${flags.has(i)?'⚑':opened.has(i)&&!mines.has(i)&&count(i)?count(i):mines.has(i)&&lost?'✹':''}</button>`).join('')}</div>${action('Restart')}</div>`);bind('xp-flag-mode',()=>{flagMode=!flagMode;draw();});const mark=i=>{if(opened.has(i)||lost)return;if(flags.has(i))flags.delete(i);else flags.add(i);draw();};root.querySelectorAll('[data-mine]').forEach(button=>{const i=Number(button.dataset.mine);button.addEventListener('contextmenu',event=>{event.preventDefault();mark(i);});button.addEventListener('click',()=>{if(flagMode){mark(i);return;}if(firstReveal){start(i);firstReveal=false;}reveal(i);if(lost){draw();say('A hidden hazard! The garden is revealed — start a fresh sweep.');return;}draw();if(opened.size===size*size-total)say('Every safe tile revealed. Perfect sweep! 🏆');else say('Safe so far. Use the numbers to map nearby hazards.');});});bind('xp-new-board',()=>{start(-1);draw();say('Fresh board. Take it one tile at a time.');});bind('xp-reset',()=>{start(-1);draw();say('Fresh board. Take it one tile at a time.');});};
